//! These functions are used by the code generated by the macro, but are not
//! intended to be used directly. None of this is covered by semver! Do not use
//! any of this directly.

use std::fmt::Display;

use crate::{error::ErrorInner, Error};


pub fn into_deserializer<'de, T>(src: T) -> <T as serde::de::IntoDeserializer<'de>>::Deserializer
where
    T: serde::de::IntoDeserializer<'de>,
{
    src.into_deserializer()
}

pub fn unwrap_or_missing_value_err<T>(value: Option<T>, path: &str) -> Result<T, Error> {
    match value {
        Some(v) => Ok(v),
        None => Err(ErrorInner::MissingValue(path.into()).into()),
    }
}

pub fn map_err_prefix_path<T>(res: Result<T, Error>, prefix: &str) -> Result<T, Error> {
    res.map_err(|mut e| {
        match &mut *e.inner {
            ErrorInner::MissingValue(path) | ErrorInner::FieldValidation { path, .. } => {
                *path = format!("{prefix}.{path}");
            }
            _ => {}
        }
        e
    })
}

/// Used by `layer!` to convert the error of deserializing a single field.
/// `path` is the path of that field, e.g. `http.port`, mentioned in the error.
pub fn map_layer_field_err(
    res: Result<(), serde::de::value::Error>,
    path: &str,
) -> Result<(), Error> {
    res.map_err(|err| ErrorInner::Deserialization {
        source: Some(format!("`layer!` field '{path}'")),
        err: Box::new(err),
    }.into())
}

pub fn validate_field<T, E: Display>(
    t: &T,
    validate: &dyn Fn(&T) -> Result<(), E>,
    path: &str,
) -> Result<(), Error> {
    validate(t).map_err(|msg| Error::field_validation(path, msg))
}

pub fn validate_struct<T, E: Display>(
    t: &T,
    validate: &dyn Fn(&T) -> Result<(), E>,
    struct_name: &'static str,
) -> Result<(), Error> {
    validate(t).map_err(|msg| ErrorInner::StructValidation {
        name: struct_name.into(),
        msg: msg.to_string()
    }.into())
}

macro_rules! get_env_var {
    ($key:expr, $field:expr) => {
        match std::env::var($key) {
            Err(std::env::VarError::NotPresent) => return Ok(None),
            Err(std::env::VarError::NotUnicode(_)) => {
                let err = ErrorInner::EnvNotUnicode {
                    key: $key.into(),
                    field: $field.into(),
                };
                return Err(err.into());
            }
            Ok(s) => s,
        }
    };
}

pub fn from_env<T>(
    key: &str,
    field: &str,
    deserialize: fn(crate::env::Deserializer) -> Result<T, crate::env::DeError>,
) -> Result<Option<T>, Error> {
    let s = get_env_var!(key, field);
    let is_empty = s.is_empty();

    match deserialize(crate::env::Deserializer::new(s)) {
        Ok(v) => Ok(Some(v)),
        Err(_) if is_empty => Ok(None),
        Err(e) => Err(ErrorInner::EnvDeserialization {
            key: key.into(),
            field: field.into(),
            msg: e.0,
        }.into()),
    }
}

pub fn from_env_with_parser<T, E: std::error::Error + Send + Sync + 'static>(
    key: &str,
    field: &str,
    parse: fn(&str) -> Result<T, E>,
    validate: fn(&T) -> Result<(), Error>,
) -> Result<Option<T>, Error> {
    let v = get_env_var!(key, field);
    let is_empty = v.is_empty();
    match parse(&v) {
        Ok(v) => {
            match validate(&v) {
                Ok(()) => Ok(Some(v)),
                Err(_) if is_empty => Ok(None),
                Err(e) => Err(e),
            }
        },
        Err(_) if is_empty => Ok(None),
        Err(err) => Err(
            ErrorInner::EnvParseError {
                field: field.to_owned(),
                key: key.to_owned(),
                err: Box::new(err),
            }.into()
        ),
    }
}

/// `serde` does implement `IntoDeserializer` for `HashMap` and `BTreeMap` but
/// we want to keep the exact source code order of entries, so we need our own
/// type.
pub struct MapIntoDeserializer<K, V>(pub Vec<(K, V)>);

impl<'de, K, V, E> serde::de::IntoDeserializer<'de, E> for MapIntoDeserializer<K, V>
where
    K: serde::de::IntoDeserializer<'de, E>,
    V: serde::de::IntoDeserializer<'de, E>,
    E: serde::de::Error,
{
    type Deserializer = serde::de::value::MapDeserializer<'de, std::vec::IntoIter<(K, V)>, E>;

    fn into_deserializer(self) -> Self::Deserializer {
        serde::de::value::MapDeserializer::new(self.0.into_iter())
    }
}

/// Used to give empty arrays and maps a type. Their element type does not
/// matter, but it must be inferable: from sibling values (e.g. `[[], [1]]`)
/// or, if there are none, it should default to `()`. Rust has no such default
/// for type parameters, but it has one for integer literals: `i32`. So these
/// functions are called with `0`. If the element type `T` is inferred from
/// somewhere else, only the `u8` impl applies. Otherwise, the literal falls
/// back to `i32` and the only `i32` impl then forces `T = ()`.
pub trait OrUnit<T> {}
impl<T> OrUnit<T> for u8 {}
impl OrUnit<()> for i32 {}

/// Empty array, see [`OrUnit`].
pub fn empty_seq<T, I: OrUnit<T>>(_: I) -> Vec<T> {
    Vec::new()
}

/// Empty map, see [`OrUnit`].
pub fn empty_map<K, V, I: OrUnit<K> + OrUnit<V>>(_: I) -> MapIntoDeserializer<K, V> {
    MapIntoDeserializer(Vec::new())
}
